<?php
require_once __DIR__.'/includes/bootstrap.php'; require_auth(); if(!in_array(role(),['admin','accueil'],true)){http_response_code(403);exit('Accès non autorisé.');}
$page_title='Dépenses';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$cat=trim($_POST['categorie']??'');$amount=(float)($_POST['montant']??0);$date=$_POST['date_depense']??date('Y-m-d');if($cat===''||$amount<=0)throw new Exception('Catégorie et montant positif obligatoires.');$s=$pdo->prepare('INSERT INTO depenses(date_depense,categorie,montant,justificatif,commentaire,enregistre_par) VALUES(?,?,?,?,?,?)');$s->execute([$date,$cat,$amount,trim($_POST['justificatif']??'')?:null,trim($_POST['commentaire']??'')?:null,$_SESSION['user']['id']]);flash('Dépense enregistrée.');}catch(Throwable $e){flash($e->getMessage(),'error');}redirect('expenses.php');}
$month=(float)$pdo->query("SELECT COALESCE(SUM(montant),0) FROM depenses WHERE MONTH(date_depense)=MONTH(CURRENT_DATE()) AND YEAR(date_depense)=YEAR(CURRENT_DATE())")->fetchColumn();$rows=$pdo->query('SELECT x.*,u.nom AS name FROM depenses x JOIN utilisateurs u ON u.id=x.enregistre_par ORDER BY x.date_depense DESC,x.id DESC LIMIT 150')->fetchAll();require 'includes/header.php';?>
<div class="cards"><div class="stat"><div class="label">Dépenses du mois</div><strong style="font-size:22px"><?=money($month)?></strong><small>Depuis le 1er du mois</small></div><div class="stat"><div class="label">Écritures affichées</div><strong><?=count($rows)?></strong><small>150 dernières au maximum</small></div></div>
<div class="panel"><h2>Enregistrer une dépense</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Date</label><input type="date" name="date_depense" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Catégorie</label><select name="categorie"><option value="loyer">Loyer</option><option value="electricite_eau">Électricité / eau</option><option value="produits_lavage">Produits de lavage</option><option value="transport">Transport</option><option value="maintenance">Maintenance / réparation</option><option value="internet_telephone">Internet / téléphone</option><option value="autre">Autre</option></select></div><div class="field"><label>Montant (FCFA)</label><input type="number" name="montant" min="1" step="1" required></div><div class="field"><label>Référence du justificatif</label><input name="justificatif" placeholder="N° reçu, facture…"></div><div class="field full"><label>Commentaire</label><textarea name="commentaire" rows="2"></textarea></div><div class="field full"><button class="btn">＋ Enregistrer la dépense</button></div></form></div>
<div class="panel"><h2>Journal des dépenses</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Catégorie</th><th>Commentaire</th><th>Justificatif</th><th>Enregistré par</th><th>Montant</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['date_depense'])?></td><td><?=e($r['categorie'])?></td><td><?=e($r['commentaire'])?></td><td><?=e($r['justificatif'])?></td><td><?=e($r['name'])?></td><td><b><?=money($r['montant'])?></b></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">Aucune dépense enregistrée.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>